module multi_pipe_4bit #(
    parameter size = 4,
    parameter N = 2 * size
) (
    input 						clk,
    input 						rst_n,
    input	[size-1:0]			mul_a,
    input	[size-1:0]			mul_b,
    output	reg	[size*2-1:0]	mul_out
);


    reg [7:0] sum_tmp1, sum_tmp2;

    always @(posedge clk , negedge rst_n)
        if(!rst_n)
            begin
               sum_tmp1 <= 8'b0;
               sum_tmp2 <= 8'b0; 
            end
        else if(rst_n)
            begin
                sum_tmp1 <= (mul_b[0]?mul_a:0) + (mul_b[1]?mul_a<<1:0);
                sum_tmp2 <= (mul_b[2]?mul_a<<2:0) + (mul_b[3]?mul_a<<3:0);
            end

    always @(posedge clk, negedge rst_n)
        if(!rst_n) sum_tmp2 <= 8'b0; else sum_tmp2 <= sum_tmp1 + sum_tmp2;

    assign mul_out = sum_tmp2;

endmodule
